from pathlib import Path
import re

p = Path('index.html')
s = p.read_text(encoding='utf-8')

css = '''.quality-title{font-size:13px;font-weight:800;color:#34445a;margin:16px 0 8px}.quality-grid{display:grid;grid-template-columns:1fr;gap:7px}.quality-option{position:relative;display:flex;align-items:center;gap:10px;padding:10px 12px;border:1px solid #d8e1eb;border-radius:12px;background:#fff;cursor:pointer}.quality-option input{position:absolute;opacity:0;pointer-events:none}.quality-dot{width:18px;height:18px;border-radius:50%;border:3px solid #d7dee7;flex:0 0 18px}.quality-option.selected{border-color:#8fb2d8;background:#f6faff}.quality-option.selected .quality-dot{border-color:#0b63ce;box-shadow:inset 0 0 0 3px #fff;background:#0b63ce}.quality-dot.q-excellent{background:#20b85a}.quality-dot.q-verygood{background:#91d99a}.quality-dot.q-passable{background:#f2d34f}.quality-dot.q-limited{background:#ef9b3f}.quality-dot.q-bad{background:#d83b3b}.check-grid{display:grid;grid-template-columns:1fr 1fr;gap:8px}.check-option{display:flex;align-items:center;gap:9px;padding:10px 11px;border:1px solid #d8e1eb;border-radius:12px;background:#fff;cursor:pointer;font-size:14px;color:#34445a}.check-option input{width:18px;height:18px;accent-color:#0b63ce;padding:0;border:0;flex:0 0 18px}.formSection{margin-top:16px}.formSection:first-of-type{margin-top:8px}.sectionHint{font-size:12px;color:#7a8798;margin:-2px 0 8px}@media(max-width:600px){.check-grid{grid-template-columns:1fr}.quality-option,.check-option{padding:11px 12px}}'''
if 'quality-grid' not in s:
    s = s.replace('.modal{', css + '\n.modal{', 1)

home_pat = r'function homeView\(user,groomer\)\{.*?\}\s*async function requestInitialLocation'
home_rep = '''function homeView(user,groomer){currentProfile={user,groomer};app.innerHTML=`<section class="card homeCard"><img class="logo" src="./logo_vestope.cz.png" alt="VeStope.cz"><div class="eyebrow">TESTOVACÍ VERZE</div><h1>Připraveno?</h1><p>Já jsem připravený. Můžeme vyrazit?</p><div id="location" class="gpsbox"><span class="gpswait">📍 Mrknu, kde právě jsi…</span></div><button id="start" class="start" disabled>START</button><div id="trackAnimation" class="track-animation" aria-hidden="true"><div class="track-base"></div><div class="track-done"></div><img class="groomer" src="./groomer.svg" alt="Sněžná rolba"><div class="snow"></div></div><div id="startStatus" class="status">GPS se připravuje. START zpřístupním, až budu mít polohu.</div><div class="account"><span>${escapeHtml(groomer?.name||user?.email||"Rolbař")}</span><button id="logout" class="secondary">Odhlásit</button></div></section>`;document.getElementById("start").addEventListener("click",()=>currentDraft?stopAndOpenForm():startTracking());document.getElementById("logout").addEventListener("click",async()=>{stopTracking();currentDraft=null;await client.auth.signOut();loginView()});requestInitialLocation(groomer?.default_area_id)}
async function requestInitialLocation'''
s, n = re.subn(home_pat, home_rep, s, count=1, flags=re.S)
if n != 1: raise SystemExit('homeView pattern not found')

req_pat = r'async function requestInitialLocation\(areaId\)\{.*?\}\s*function renderLocation'
req_rep = '''async function requestInitialLocation(areaId){const el=document.getElementById("location"),status=document.getElementById("startStatus"),button=document.getElementById("start");if(!navigator.geolocation){el.innerHTML='<span class="gpserror">GPS toto zařízení nepodporuje.</span>';status.textContent="Bez GPS dnes nevyrazíme.";return}status.textContent="Mrknu, kde právě jsi…";navigator.geolocation.getCurrentPosition(async position=>{const nearest=await detectNearestStart(position,areaId);renderLocation(el,position,nearest);button.disabled=false;button.dataset.gpsReady="true";status.className="status";status.innerHTML='<span class="gpsok">✓ GPS mám. Můžeš vyrazit.</span>'},error=>{button.disabled=true;button.dataset.gpsReady="false";el.innerHTML='<span class="gpserror">📍 GPS zatím nevidím.</span><br><span style="font-size:12px;color:#8290a0">Povol přístup k poloze a zkus to znovu.</span>';status.textContent=error.code===1?"Poloha není povolená. Bez GPS START nespustím.":"Poloha není momentálně dostupná. START počká, až ji chytím."},{enableHighAccuracy:true,timeout:15000,maximumAge:0})}
function renderLocation'''
s, n = re.subn(req_pat, req_rep, s, count=1, flags=re.S)
if n != 1: raise SystemExit('requestInitialLocation pattern not found')

start_pat = r'function startTracking\(\)\{.*?\}\s*function startGpsWatch'
start_rep = '''function startTracking(){const button=document.getElementById("start"),status=document.getElementById("startStatus"),animation=document.getElementById("trackAnimation");if(button.disabled||button.dataset.gpsReady!=="true"){status.textContent="Ještě nemám potvrzenou GPS. START je zatím zamčený.";return}button.disabled=true;button.textContent="GPS…";status.textContent="Chytám přesnou polohu a vyrážíme…";navigator.geolocation.getCurrentPosition(async position=>{currentDraft={id:crypto.randomUUID(),startedAt:new Date().toISOString(),synced:false,points:[],startLat:position.coords.latitude,startLon:position.coords.longitude,startAccuracy:position.coords.accuracy,startName:null};saveGpsPoint(currentDraft,position);localStorage.setItem("vestope:groomer:phaseA:draft",JSON.stringify(currentDraft));startGpsWatch(currentDraft);button.disabled=false;button.dataset.gpsReady="true";button.textContent="STOP";animation.classList.add("active");const nearest=await detectNearestStart(position,currentProfile?.groomer?.default_area_id);currentDraft.startName=nearest?.name||null;renderLocation(document.getElementById("location"),position,nearest);status.className="status running";status.textContent="Jedu s tebou. GPS běží."},error=>{button.disabled=true;button.dataset.gpsReady="false";button.textContent="START";status.className="status";status.style.color="#b3261e";if(error.code===1)status.textContent="Přístup k GPS byl zamítnut. Povol GPS v nastavení zařízení.";else if(error.code===2)status.textContent="Poloha není momentálně dostupná. START zůstává zamčený.";else status.textContent="GPS se nepodařilo získat. START zůstává zamčený."},{enableHighAccuracy:true,timeout:15000,maximumAge:0})}
function startGpsWatch'''
s, n = re.subn(start_pat, start_rep, s, count=1, flags=re.S)
if n != 1: raise SystemExit('startTracking pattern not found')

form_pat = r'function openStopForm\(\)\{.*?\}\s*const thanks='
form_rep = """function openStopForm(){const started=currentDraft?.startedAt?new Date(currentDraft.startedAt):new Date();const minutes=Math.max(1,Math.round((Date.now()-started.getTime())/60000));document.body.insertAdjacentHTML(\"beforeend\",`<div class=\"modal\" id=\"stopModal\"><div class=\"modalCard\"><div class=\"eyebrow\">JÍZDA UKONČENA</div><h2>STOP. Dobrá práce.</h2><div class=\"lead\">Ještě mi řekni, jak to dneska vypadalo. Zaznamenal jsem přibližně ${minutes} min · ${currentDraft?.points?.length||0} GPS bodů.</div><form id=\"stopForm\"><div class=\"formSection\"><div class=\"quality-title\">Jaká je podle tebe stopa?</div><div class=\"quality-grid\" id=\"qualityGrid\"><label class=\"quality-option selected\"><input type=\"radio\" name=\"trackQuality\" value=\"excellent\" checked><span class=\"quality-dot q-excellent\"></span><span>Výborná</span></label><label class=\"quality-option\"><input type=\"radio\" name=\"trackQuality\" value=\"very-good\"><span class=\"quality-dot q-verygood\"></span><span>Velmi dobrá</span></label><label class=\"quality-option\"><input type=\"radio\" name=\"trackQuality\" value=\"passable\"><span class=\"quality-dot q-passable\"></span><span>Sjízdné</span></label><label class=\"quality-option\"><input type=\"radio\" name=\"trackQuality\" value=\"limited\"><span class=\"quality-dot q-limited\"></span><span>Sjízdné s většími omezeními</span></label><label class=\"quality-option\"><input type=\"radio\" name=\"trackQuality\" value=\"bad\"><span class=\"quality-dot q-bad\"></span><span>Nesjízdné</span></label></div></div><div class=\"formSection\"><h3>Sněhové podmínky</h3><div class=\"sectionHint\">Můžeš vybrat jednu i více možností.</div><div class=\"check-grid\"><label class=\"check-option\"><input type=\"checkbox\" name=\"snowCondition\" value=\"powder\">Prachový sníh</label><label class=\"check-option\"><input type=\"checkbox\" name=\"snowCondition\" value=\"soft\">Měkká bořivá stopa</label><label class=\"check-option\"><input type=\"checkbox\" name=\"snowCondition\" value=\"wet-heavy\">Mokrý těžký sníh</label><label class=\"check-option\"><input type=\"checkbox\" name=\"snowCondition\" value=\"icy-fast\">Zledovatělá rychlá stopa</label><label class=\"check-option\"><input type=\"checkbox\" name=\"snowCondition\" value=\"lightly-dirty\">Málo znečištěná stopa</label><label class=\"check-option\"><input type=\"checkbox\" name=\"snowCondition\" value=\"heavily-dirty\">Silně znečištěná stopa</label><label class=\"check-option\"><input type=\"checkbox\" name=\"snowCondition\" value=\"firn\">Starý jarní firn</label><label class=\"check-option\"><input type=\"checkbox\" name=\"snowCondition\" value=\"technical\">Technický umělý sníh</label></div></div><div class=\"formSection\"><h3>Druh stopy</h3><div class=\"sectionHint\">Vyber, co je dnes upravené.</div><div class=\"check-grid\"><label class=\"check-option\"><input type=\"checkbox\" name=\"trackType\" value=\"classic\">Klasika</label><label class=\"check-option\"><input type=\"checkbox\" name=\"trackType\" value=\"skate\">Skate (bruslení)</label></div></div><div class=\"formSection\"><label for=\"note\">Poznámka <span style=\"font-weight:400;color:#8a96a5\">(nepovinné)</span></label><textarea id=\"note\" placeholder=\"Třeba: mezi Brunstem a Můstkem fouká…\"></textarea></div><div class=\"formActions\"><button type=\"button\" class=\"cancel\" id=\"cancelStop\">Zpět</button><button class=\"save\">Uložit jízdu</button></div></form></div></div>`);document.querySelectorAll('#qualityGrid input[name=\"trackQuality\"]').forEach(input=>input.addEventListener('change',()=>{document.querySelectorAll('#qualityGrid .quality-option').forEach(x=>x.classList.toggle('selected',x.contains(input)&&input.checked))}));document.getElementById(\"cancelStop\").addEventListener(\"click\",()=>{document.getElementById(\"stopModal\")?.remove();currentDraft=null;homeView(currentProfile.user,currentProfile.groomer)});document.getElementById(\"stopForm\").addEventListener(\"submit\",saveRide)}
const thanks="""
s, n = re.subn(form_pat, form_rep, s, count=1, flags=re.S)
if n != 1: raise SystemExit('openStopForm pattern not found')

save_pat = r'function saveRide\(e\)\{.*?\}\s*function showThanks'
save_rep = '''function saveRide(e){e.preventDefault();const quality=document.querySelector('input[name="trackQuality"]:checked')?.value||"excellent";const snowConditions=[...document.querySelectorAll('input[name="snowCondition"]:checked')].map(x=>x.value);const trackTypes=[...document.querySelectorAll('input[name="trackType"]:checked')].map(x=>x.value);const record={...currentDraft,endedAt:new Date().toISOString(),synced:false,questionnaire:{trackQuality:quality,snowConditions,trackTypes,note:document.getElementById("note").value.trim()}};const rides=JSON.parse(localStorage.getItem("vestope:groomer:rides")||"[]");rides.push(record);localStorage.setItem("vestope:groomer:rides",JSON.stringify(rides));localStorage.removeItem("vestope:groomer:phaseA:draft");currentDraft=null;document.getElementById("stopModal")?.remove();showThanks(quality)}
function showThanks'''
s, n = re.subn(save_pat, save_rep, s, count=1, flags=re.S)
if n != 1: raise SystemExit('saveRide pattern not found')

p.write_text(s, encoding='utf-8')
